/** Full logo as on remocn.dev: R mark (0.76em tall, baseline-aligned) + "emocn" in Manrope 600. */
function RemocnLogo({ fontSize, color }: { fontSize: number; color: string }) {
  return (
    <div
      style={{
        display: "flex",
        alignItems: "baseline",
        color,
        fontFamily: manrope.fontFamily,
        fontWeight: 600,
        fontSize,
        letterSpacing: "-0.025em",
        lineHeight: 1,
      }}
    >
      <svg
        viewBox="0 0 124.06 134.26"
        style={{ height: "0.76em", width: "auto" }}
        aria-hidden
      >
        <path fill="currentColor" d={REMOCN_R_PATH} />
      </svg>
      <span style={{ marginLeft: "0.04em" }}>emocn</span>
    </div>
  );
}

interface ComboRating {
  /** The hit count this rating kicks in at. */
  from: number;
  text: string;
}

interface ComboCounterProps {
  /** One hit per feature, in order. The combo count is the number of hits landed. */
  hits?: string[];
  /** Ratings, swapped in as the count passes `from`. The last one is the poster's. */
  ratings?: ComboRating[];
  /** Small marker next to the rating. */
  accent?: string;
  /** Big word next to the count. */
  hitLabel?: string;
  /** Small caps label under `hitLabel`. */
  comboLabel?: string;
  /** Text color; overrides the theme ink. */
  ink?: string;
  /** Background fill; "transparent" drops it. */
  background?: string;
  /** Typeface for the copy. Load it yourself; Saira by default. */
  fontFamily?: string;
  /** Replaces the remocn mark under the poster. */
  logo?: React.ReactNode;
  /** Size of the foreground, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  theme?: "dark" | "light";
  speed?: number;
}

// Beat sheet (30fps, speed 1):
//   6–66   twelve feature names hit one after another, the gaps shrinking from
//          8 frames to 4; each lands as a hit-spark (star flash + gradient
//          slash + the word slamming in from 1.4×) and fades after ~10 frames
//  14–66  the combo meter on the left counts from 2 up, every hit scales and
//          shakes it a bit harder; the rating swaps Nice → Great → PERFECT
//  66     finisher: the 12th hit, the frame flashes, PERFECT slams in
//  72–86  the meter glides to the centre and scales up into the poster, the
//          number fills with the "swirl" gradient
//  92–    the logo rises in, poster hold
const HIT_GAPS = [8, 7, 7, 6, 6, 5, 5, 4, 4, 4, 4];
const FIRST_HIT = 6;
const WORD_LIFE = 11;
const GLIDE_DELAY = 6;
const GLIDE_LEN = 14;
const FILL_DELAY = 10;
const FILL_LEN = 10;
const LOGO_DELAY = 26;

const SLAM = Easing.bezier(0.12, 0.9, 0.25, 1);
const OUT = Easing.bezier(0.22, 1, 0.36, 1);
const INOUT = Easing.bezier(0.65, 0, 0.25, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

// gradients.sh "swirl": bg #07060a, [#ffe2c4, #ff9a4d, #d2456b, #3a1f6b].
const SWIRL = ["#FFE2C4", "#FF9A4D", "#D2456B", "#3A1F6B"] as const;

const THEMES = {
  dark: {
    stage: "#08070B",
    ink: "#F3F2EF",
    dim: "#8A8990",
    flash: "#FFFFFF",
    number: `linear-gradient(170deg, ${SWIRL[0]} 6%, ${SWIRL[1]} 38%, ${SWIRL[2]} 72%, #8E3A9E 100%)`,
  },
  light: {
    stage: "#F5F4F0",
    ink: "#121214",
    dim: "#7E7D77",
    flash: "#FFFFFF",
    number: `linear-gradient(170deg, ${SWIRL[1]} 4%, ${SWIRL[2]} 50%, ${SWIRL[3]} 100%)`,
  },
} as const;

// Where each hit lands, centre of the word, in units of W and H.
const SLOTS = [
  { x: 0.67, y: 0.3, r: -4 },
  { x: 0.79, y: 0.54, r: 3 },
  { x: 0.63, y: 0.74, r: -2 },
  { x: 0.8, y: 0.22, r: 4 },
  { x: 0.66, y: 0.5, r: -3 },
  { x: 0.78, y: 0.8, r: 2 },
];

// Long hit-slashes that stay behind the poster.
const POSTER_SLASHES = [
  { dx: -0.06, dy: 0, len: 0.42, thick: 9, delay: 0, op: 0.9 },
  { dx: 0.1, dy: 0.07, len: 0.26, thick: 4, delay: 2, op: 0.7 },
  { dx: -0.16, dy: -0.08, len: 0.18, thick: 3, delay: 3, op: 0.5 },
];

function ramp(t: number, from: number, len: number) {
  return interpolate(t, [from, from + len], [0, 1], CLAMP);
}

/** A short hit: up in 1 frame, eases back over `len`. */
function kick(d: number, len = 8) {
  if (d < 0) return 0;
  if (d < 1) return d;
  const k = Math.max(0, 1 - (d - 1) / len);
  return k * k;
}

function starPath(L: number, w: number) {
  return `M0 ${-L} L${w} ${-w} L${L} 0 L${w} ${w} L0 ${L} L${-w} ${w} L${-L} 0 L${-w} ${-w} Z`;
}

const midway = (p: number) => p > 0 && p < 1;

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

function ComboCounterBase({
  hits = [
    "Captions",
    "Transitions",
    "Logo reveal",
    "Backgrounds",
    "Charts",
    "Text effects",
    "Lower thirds",
    "Mockups",
    "Countdowns",
    "Kinetic type",
    "Particles",
    "Templates",
  ],
  ratings = [
    { from: 2, text: "Nice" },
    { from: 6, text: "Great" },
    { from: 12, text: "PERFECT" },
  ],
  accent = "#3B5BFD",
  hitLabel = "HIT",
  comboLabel = "COMBO",
  ink,
  background,
  fontFamily = sairaItalic,
  logo,
  scale = 1,
  delay = 0,
  theme = "dark",
  speed = 1,
}: ComboCounterProps) {
  // `glide` is the meter's move to the poster below.
  const tilt = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H } = useSceneConfig();
  const c = THEMES[theme];
  const fg = ink ?? c.ink;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.stage);
  const u = Math.min(W / 1280, H / 720);
  const id = useId().replace(/[^a-zA-Z0-9_-]/g, "");

  const times: number[] = [];
  hits.forEach((_, i) => {
    times.push(
      i === 0
        ? FIRST_HIT
        : times[i - 1] + (HIT_GAPS[i - 1] ?? HIT_GAPS[HIT_GAPS.length - 1]),
    );
  });
  const lastAt = times[times.length - 1] ?? FIRST_HIT;

  // ── Meter ─────────────────────────────────────────────────────────────────
  const numFs = 210 * u;
  const hitFs = 66 * u;
  const comboFs = 30 * u;
  const rateFs = 70 * u;
  const digits = String(hits.length).length;
  const blockW = digits * 0.6 * numFs + 0.24 * numFs + 2.1 * hitFs;
  const posterK = 1.65;

  // Everything that moves the meter and its text, as a function of the frame,
  // so the frames either side can tell whether it is moving.
  const meterAt = (tt: number) => {
    const n = times.filter((h) => tt >= h).length;
    const lastHit = n > 0 ? times[n - 1] : -99;
    const final = n === hits.length;
    const meterIn = n >= 2 ? OUT(ramp(tt, times[1], 6)) : 0;
    const d = tt - lastHit;
    const hitAmp = final ? 0.24 : 0.08 + 0.012 * n;
    const pop = 1 + hitAmp * kick(d, final ? 10 : 6);
    const shakeAmp = (final ? 16 : 3 + 0.9 * n) * u;
    const sd = Math.floor(d);
    const shakeK = sd >= 0 && sd < 8 ? (1 - sd / 8) ** 2 : 0;
    const shx = shakeAmp * shakeK * Math.sin(sd * 2.7 + 0.4);
    const shy = shakeAmp * 0.5 * shakeK * Math.cos(sd * 3.3);

    // Glide to the poster: the meter block is laid out from its left edge, so
    // the target x centres an estimate of its width (number + label column).
    const glide = INOUT(ramp(tt, lastAt + GLIDE_DELAY, GLIDE_LEN));
    const gx = interpolate(
      glide,
      [0, 1],
      [0.075 * W, W / 2 - (blockW * posterK) / 2],
    );
    const gy = interpolate(glide, [0, 1], [0.47 * H, 0.47 * H]);
    const gk = interpolate(glide, [0, 1], [1, posterK]);
    const rates = ratings.flatMap((r, k) => {
      const startAt = times[r.from - 1];
      const endAt =
        ratings[k + 1] !== undefined
          ? times[ratings[k + 1].from - 1]
          : undefined;
      if (startAt === undefined) return [];
      return [
        SLAM(ramp(tt, startAt, 5)),
        endAt !== undefined ? ramp(tt, endAt, 2) : 0,
      ];
    });
    const sig = [shx, shy, gx, gk, pop, meterIn, ...rates];
    return { n, meterIn, pop, shx, shy, glide, gx, gy, gk, sig };
  };
  const { n, meterIn, pop, shx, shy, glide, gx, gy, gk, sig } = meterAt(t);
  const stepped = (f: number) =>
    meterAt(f).sig.some((v, i) => Math.abs(v - sig[i]) > 1e-5);
  const meterMoving = stepped(t + speed) || stepped(t - speed);
  // The meter is laid out where the glide to the poster lands and travels
  // there by a transform all its life: a block moved by `left` rounds its
  // edges to whole pixels and steps unevenly, and a hand-over between the two
  // would jump by the rounding.
  const gxRest = meterAt(lastAt + GLIDE_DELAY + GLIDE_LEN).gx;
  const fillP = OUT(ramp(t, lastAt + FILL_DELAY, FILL_LEN));
  const logoP = OUT(ramp(t, lastAt + LOGO_DELAY, 10));

  const numberGlyphs = (text: string, gradient: boolean) => (
    <div
      style={{
        fontFamily,
        fontStyle: "italic",
        fontWeight: 500,
        fontSize: numFs,
        lineHeight: 0.8,
        letterSpacing: "-0.03em",
        paddingRight: 0.08 * numFs,
        fontVariantNumeric: "tabular-nums",
        whiteSpace: "nowrap",
        ...(gradient
          ? {
              backgroundImage: c.number,
              WebkitBackgroundClip: "text",
              backgroundClip: "text",
              color: "transparent",
            }
          : { color: fg }),
      }}
    >
      {text}
    </div>
  );

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <svg width={0} height={0} style={{ position: "absolute" }} aria-hidden>
        <defs>
          <linearGradient id={`${id}-sw`} x1="0" y1="0" x2="1" y2="1">
            <stop offset="0" stopColor={SWIRL[0]} />
            <stop offset="0.45" stopColor={SWIRL[1]} />
            <stop offset="1" stopColor={SWIRL[2]} />
          </linearGradient>
        </defs>
      </svg>

      <ScaleLayer scale={scale}>
        {/* Hit-sparks: one per feature. */}
        {hits.map((word, i) => {
          const h = times[i];
          const dd = t - h;
          if (dd < 0 || dd > WORD_LIFE + 4) return null;
          const slot = SLOTS[i % SLOTS.length];
          const x = slot.x * W;
          const y = slot.y * H;
          const isFinal = i === hits.length - 1;
          const wordIn = SLAM(ramp(dd, 0, 4));
          const out = ramp(dd, WORD_LIFE - 3, 5);
          const starP = ramp(dd, 0, 7);
          const L =
            interpolate(OUT(starP), [0, 1], [50, isFinal ? 190 : 120]) * u;
          const streak = OUT(ramp(dd, 0, 3));
          const streakOut = ramp(dd, 3, 6);
          const sl = 0.2 * W * streak;
          return (
            <div key={`${i}-${word}`}>
              <svg
                width={W}
                height={H}
                style={{ position: "absolute", inset: 0 }}
                aria-hidden
              >
                <g
                  transform={`translate(${x} ${y}) rotate(${-22 + slot.r})`}
                  opacity={1 - streakOut}
                >
                  <path
                    d={`M${-sl} 0 L0 ${-5 * u} L${sl} 0 L0 ${5 * u} Z`}
                    fill={`url(#${id}-sw)`}
                  />
                </g>
                <g
                  transform={`translate(${x - word.length * 0.25 * 62 * u - 34 * u} ${y - 6 * u})`}
                  opacity={1 - starP}
                >
                  <path d={starPath(L, 7 * u)} fill={`url(#${id}-sw)`} />
                  <path
                    d={starPath(L * 0.45, 4 * u)}
                    fill={c.flash}
                    transform="rotate(45)"
                  />
                </g>
              </svg>
              <div
                style={{
                  position: "absolute",
                  left: x - 0.3 * W,
                  width: 0.6 * W,
                  top: y - 50 * u,
                  height: 100 * u,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  transform: `translateY(${-18 * u * out}px) rotate(${slot.r}deg) scale(${interpolate(wordIn, [0, 1], [1.4, 1]) * (1 - 0.08 * out)})`,
                  opacity: ramp(dd, 0, 2) * (1 - out),
                  fontFamily,
                  fontStyle: "italic",
                  fontWeight: 500,
                  fontSize: 62 * u,
                  lineHeight: 1,
                  letterSpacing: "-0.01em",
                  color: fg,
                  whiteSpace: "nowrap",
                }}
              >
                {word}
              </div>
            </div>
          );
        })}

        {/* Poster slashes behind the meter. */}
        {glide > 0 ? (
          <svg
            width={W}
            height={H}
            style={{ position: "absolute", inset: 0 }}
            aria-hidden
          >
            {POSTER_SLASHES.map((p) => {
              const g = OUT(ramp(t, lastAt + GLIDE_DELAY + 6 + p.delay, 8));
              const len = p.len * W * g;
              return (
                <g
                  key={p.dy}
                  transform={`translate(${W / 2 + p.dx * W} ${0.4 * H + p.dy * H}) rotate(-22)`}
                >
                  <path
                    d={`M${-len} 0 L0 ${-p.thick * u} L${len} 0 L0 ${p.thick * u} Z`}
                    fill={`url(#${id}-sw)`}
                    opacity={p.op}
                  />
                </g>
              );
            })}
          </svg>
        ) : null}

        {/* The combo meter. */}
        {n >= 2 ? (
          <div
            style={{
              position: "absolute",
              left: gxRest,
              top: gy,
              // Covers the number, the labels and the rating inside it.
              transform: `translateX(${gx - gxRest}px) translate(${shx}px, ${shy}px) translateY(-50%) scale(${gk})${tilt(meterMoving)}`,
              transformOrigin: "0% 50%",
              opacity: meterIn,
            }}
          >
            <div
              style={{
                display: "flex",
                alignItems: "flex-end",
                gap: 0.16 * numFs,
              }}
            >
              <div
                style={{
                  position: "relative",
                  transform: `scale(${pop * interpolate(meterIn, [0, 1], [1.5, 1])})`,
                  transformOrigin: "100% 100%",
                }}
              >
                {numberGlyphs(String(n), false)}
                {fillP > 0 ? (
                  <div
                    style={{
                      position: "absolute",
                      inset: 0,
                      clipPath: `inset(0 ${(1 - fillP) * 100}% 0 0)`,
                    }}
                  >
                    {numberGlyphs(String(n), true)}
                  </div>
                ) : null}
              </div>
              <div
                style={{
                  display: "flex",
                  flexDirection: "column",
                  paddingBottom: 0.02 * numFs,
                }}
              >
                <div
                  style={{
                    fontFamily,
                    fontStyle: "italic",
                    fontWeight: 500,
                    fontSize: hitFs,
                    lineHeight: 0.9,
                    letterSpacing: "0.01em",
                    color: fg,
                  }}
                >
                  {hitLabel}
                </div>
                <div
                  style={{
                    fontFamily,
                    fontWeight: 500,
                    fontSize: comboFs,
                    lineHeight: 1,
                    letterSpacing: "0.28em",
                    color: c.dim,
                    marginTop: 0.12 * hitFs,
                  }}
                >
                  {comboLabel}
                </div>
              </div>
            </div>

            {/* Rating: swaps as the combo climbs. */}
            <div
              style={{
                position: "relative",
                height: rateFs * 1.2,
                marginTop: 0.14 * numFs,
              }}
            >
              {ratings.map((r, k) => {
                const startAt = times[r.from - 1];
                if (startAt === undefined) return null;
                const next = ratings[k + 1];
                const endAt = next ? times[next.from - 1] : undefined;
                if (t < startAt) return null;
                if (endAt !== undefined && t >= endAt + 2) return null;
                const inP = SLAM(ramp(t, startAt, 5));
                const outP = endAt !== undefined ? ramp(t, endAt, 2) : 0;
                const isLast = k === ratings.length - 1;
                return (
                  <div
                    key={r.text}
                    style={{
                      position: "absolute",
                      left: 0,
                      top: 0,
                      display: "flex",
                      alignItems: "center",
                      gap: 0.28 * rateFs,
                      transform: `translateY(${-0.5 * rateFs * outP}px) scale(${interpolate(inP, [0, 1], [1.45, 1])})`,
                      transformOrigin: "0% 50%",
                      opacity:
                        ramp(t, startAt + (k > 0 ? 1 : 0), 2) * (1 - outP),
                      whiteSpace: "nowrap",
                    }}
                  >
                    <div
                      style={{
                        width: 0.16 * rateFs,
                        height: 0.62 * rateFs,
                        background: accent,
                        transform: "skewX(-14deg)",
                      }}
                    />
                    <div
                      style={{
                        fontFamily,
                        fontStyle: "italic",
                        fontWeight: isLast ? 500 : 400,
                        fontSize: rateFs,
                        lineHeight: 1,
                        letterSpacing: isLast ? "0.06em" : "-0.01em",
                        color: fg,
                      }}
                    >
                      {r.text}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        ) : null}

        {/* Logo. */}
        <div
          style={{
            position: "absolute",
            left: 0,
            width: W,
            top: 0.88 * H,
            display: "flex",
            justifyContent: "center",
            opacity: logoP,
            transform: `translateY(${(1 - logoP) * 16 * u}px)${tilt(midway(logoP))}`,
          }}
        >
          {logo ?? <RemocnLogo fontSize={30 * u} color={c.ink} />}
        </div>
      </ScaleLayer>
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  hitLabel: {
    type: "text-content",
    default: "HIT",
    description: "Hit label",
  },
  comboLabel: {
    type: "text-content",
    default: "COMBO",
    description: "Combo label",
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  fontFamily: {
    type: "font-family",
    default: "Saira",
    description: "Font",
  },
  ink: {
    type: "color",
    default: undefined,
    description: "Text color",
  },
  background: {
    type: "color",
    default: undefined,
    description: "Background",
  },
  scale: {
    type: "number",
    default: 1,
    min: 0.5,
    max: 1.5,
    step: 0.05,
    description: "Scale",
    hiddenFromList: false,
  },
  delay: {
    type: "number",
    default: 0,
    min: 0,
    max: 60,
    step: 1,
    description: "Delay (frames)",
    hiddenFromList: false,
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","hitLabel","comboLabel","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  hitLabel: "HIT",
  comboLabel: "COMBO",
  accent: "#3B5BFD",
  fontFamily: "Saira",
  scale: 1,
  delay: 0,
  speed: 1,
};

type ComboCounterElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ComboCounterBase>;

const ComboCounterInner = forwardRef<
  HTMLDivElement,
  ComboCounterElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ComboCounter>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ComboCounterBase
          {...(componentProps as unknown as ComponentProps<typeof ComboCounterBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ComboCounter = Interactive.withSchema({
  Component: ComboCounterInner,
  componentName: "<ComboCounter>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
